create table if not exists private.legacy_cave_security_import_eligibility(user_id uuid primary key references auth.users(id)on delete cascade,granted_at timestamptz not null default now());insert into private.legacy_cave_security_import_eligibility(user_id)select distinct user_id from private.player_cave_states where not security_v2_initialized on conflict do nothing;alter table private.legacy_cave_security_import_eligibility enable row level security;revoke all on private.legacy_cave_security_import_eligibility from public,anon,authenticated;

create or replace function private.server_all_books_mastered(p_user uuid,p_channel text)returns boolean language plpgsql stable security definer set search_path='' as $$declare e private.player_permanent_consumable_effects;mastered integer;begin select * into e from private.player_permanent_consumable_effects where user_id=p_user and channel=p_channel;if e.user_id is null then return false;end if;select count(*)into mastered from jsonb_array_elements_text(e.learned_books)x(id)where id~'^artbook-(secret|formula|sutra|escape)-t[1-9]-(metal|wood|water|fire|earth)-[12]$'and coalesce((e.art_levels->>id)::integer,1)>=10;return mastered=360;exception when invalid_text_representation or numeric_value_out_of_range then return false;end$$;

create or replace function private.refresh_qi_profile(p_uid uuid,p_channel text)returns numeric language plpgsql security definer set search_path='' as $$declare p private.player_progression_states;c private.player_cave_states;w private.player_resource_wallets;profile jsonb;core jsonb;comprehension numeric;base_rate numeric;cycle_bonus numeric;cave_bonus numeric;final_rate numeric;begin select * into p from private.player_progression_states where user_id=p_uid and channel=p_channel;select * into c from private.player_cave_states where user_id=p_uid and channel=p_channel;select * into w from private.player_resource_wallets where user_id=p_uid and channel=p_channel for update;if p.user_id is null or w.user_id is null then return 0;end if;profile:=coalesce(w.earning_profile,'{}'::jsonb);core:=private.server_base_core(p_uid,p_channel);comprehension:=coalesce((core->>'comprehension')::numeric,0)+case when private.server_all_books_mastered(p_uid,p_channel)then 500 else 0 end;base_rate:=case when p.cultivation_awakened and p.spirit_path_opened then floor((10+floor(2+3*sqrt(greatest(0,comprehension-5))))*private.path_efficiency(p.spirit_level))else 0 end;cycle_bonus:=case p.qi_cycle when'small'then .08+least(8,p.qi_mark_small)*.0075 when'origin'then .04 else .02 end;cave_bonus:=case when c.user_id is not null and c.cultivation_enabled and c.spirit_path_opened then .08+c.cultivation_level*.02 else 0 end;final_rate:=floor(base_rate*(1+cycle_bonus)*(1+cave_bonus));profile:=profile||jsonb_build_object('base_cultivation_rate',base_rate::text,'qi_cycle_bonus',cycle_bonus::text,'cave_cultivation_bonus',cave_bonus::text,'cultivation_rate',final_rate::text);update private.player_resource_wallets set earning_profile=profile,updated_at=now()where user_id=p_uid and channel=p_channel;return final_rate;end$$;

create or replace function private.refresh_resource_profile_authoritative(p_uid uuid,p_channel text)returns jsonb language plpgsql security definer set search_path='' as $$declare p private.player_progression_states;c private.player_cave_states;w private.player_resource_wallets;profile jsonb;core jsonb;fortune numeric;pool_bonus numeric;sword_base numeric;sword_bonus numeric;begin perform private.refresh_qi_profile(p_uid,p_channel);select * into p from private.player_progression_states where user_id=p_uid and channel=p_channel;select * into c from private.player_cave_states where user_id=p_uid and channel=p_channel;select * into w from private.player_resource_wallets where user_id=p_uid and channel=p_channel for update;if p.user_id is null or c.user_id is null or w.user_id is null then raise exception '伺服器資源狀態尚未建立';end if;profile:=coalesce(w.earning_profile,'{}'::jsonb);core:=private.server_base_core(p_uid,p_channel);fortune:=coalesce((core->>'fortune')::numeric,0)+case when private.server_all_books_mastered(p_uid,p_channel)then 500 else 0 end;pool_bonus:=least(greatest(c.spirit_pool_level-1,0),9)*2+least(greatest(c.spirit_pool_level-10,0),10)*3+greatest(c.spirit_pool_level-20,0)*4;sword_base:=case when p.cultivation_awakened and p.sword_path_opened then floor(12.5*private.path_efficiency(p.sword_level))else 0 end;sword_bonus:=case when c.sword_enabled and c.sword_path_opened and c.has_sword_embryo then .08+c.sword_level*.02 else 0 end;profile:=profile||jsonb_build_object('base_sword_rate',sword_base::text,'cave_sword_bonus',sword_bonus::text,'sword_rate',floor(sword_base*(1+sword_bonus))::text,'pool_bonus',pool_bonus::text,'aura_rate',greatest(1,floor(5+pool_bonus+2.5*sqrt(greatest(0,fortune))))::text,'aura_capacity',floor(20000*power(c.spirit_pool_level::numeric,1.35))::text,'food_workers',least(c.worker_food,floor(c.food_area_level*3.5)::integer),'wood_workers',least(c.worker_wood,c.wood_area_level*2),'iron_workers',least(c.worker_iron,c.iron_area_level),'food_capacity',(180::numeric*c.food_area_level*c.food_area_level-180*c.food_area_level+4800)::text,'wood_capacity',(120::numeric*c.wood_area_level*c.wood_area_level-120*c.wood_area_level+720)::text,'iron_capacity',(60::numeric*c.iron_area_level*c.iron_area_level-60*c.iron_area_level+360)::text);update private.player_resource_wallets set earning_profile=profile,updated_at=now()where user_id=p_uid and channel=p_channel;return profile;end$$;

create or replace function public.player_resource_profile_bootstrap(p_channel text,p_profile jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());begin if uid is null then raise exception 'authentication required';end if;if p_channel not in('formal','test')then raise exception 'invalid request';end if;return private.refresh_resource_profile_authoritative(uid,p_channel);end$$;

create or replace function private.refresh_cave_profile(uid uuid,p_channel text,c private.player_cave_states)returns void language plpgsql security definer set search_path='' as $$begin perform private.refresh_resource_profile_authoritative(uid,p_channel);end$$;
create or replace function private.refresh_facility_profile(uid uuid,p_channel text,c private.player_cave_states)returns void language plpgsql security definer set search_path='' as $$begin perform private.refresh_resource_profile_authoritative(uid,p_channel);end$$;

create or replace function public.player_cave_security_bootstrap(p_channel text,p_config jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());c private.player_cave_states;eligible boolean;begin if uid is null then raise exception 'authentication required';end if;if p_channel not in('formal','test')or jsonb_typeof(p_config)<>'object'then raise exception 'invalid request';end if;select exists(select 1 from private.legacy_cave_security_import_eligibility where user_id=uid)into eligible;select * into c from private.player_cave_states where user_id=uid and channel=p_channel for update;if c.user_id is null then raise exception 'cave state not initialized';end if;if not c.security_v2_initialized then if eligible then update private.player_cave_states set security_v2_initialized=true,cave_core_level=least(7,greatest(1,coalesce((p_config->>'caveCoreLevel')::integer,1))),cultivation_level=least(7,greatest(1,coalesce((p_config->>'caveCultivationLevel')::integer,1))),sword_level=least(7,greatest(1,coalesce((p_config->>'caveSwordLevel')::integer,1))),body_level=least(7,greatest(1,coalesce((p_config->>'caveBodyLevel')::integer,1))),cultivation_enabled=coalesce((p_config->>'caveCultivationEnabled')::boolean,false),sword_enabled=coalesce((p_config->>'caveSwordEnabled')::boolean,false),body_enabled=coalesce((p_config->>'caveBodyEnabled')::boolean,false),spirit_path_opened=coalesce((p_config->>'spiritPathOpened')::boolean,false),sword_path_opened=coalesce((p_config->>'swordPathOpened')::boolean,false),body_path_opened=coalesce((p_config->>'bodyPathOpened')::boolean,false),has_sword_embryo=coalesce(length(p_config->>'swordEmbryo')>0,false),metal_root=least(200,greatest(0,coalesce((p_config->>'metalRoot')::integer,0))),wood_root=least(200,greatest(0,coalesce((p_config->>'woodRoot')::integer,0))),water_root=least(200,greatest(0,coalesce((p_config->>'waterRoot')::integer,0))),fire_root=least(200,greatest(0,coalesce((p_config->>'fireRoot')::integer,0))),earth_root=least(200,greatest(0,coalesce((p_config->>'earthRoot')::integer,0))),updated_at=now()where user_id=uid and channel=p_channel returning * into c;delete from private.legacy_cave_security_import_eligibility where user_id=uid;else update private.player_cave_states set security_v2_initialized=true where user_id=uid and channel=p_channel returning * into c;end if;end if;perform private.refresh_resource_profile_authoritative(uid,p_channel);return private.cave_snapshot(c);exception when invalid_text_representation or numeric_value_out_of_range then raise exception 'invalid cave configuration';end$$;

select private.refresh_resource_profile_authoritative(p.user_id,p.channel)from private.player_progression_states p join private.player_cave_states c using(user_id,channel)join private.player_resource_wallets w using(user_id,channel)join private.player_identity_states i using(user_id,channel)join private.player_body_states b using(user_id,channel);

revoke all on function private.server_all_books_mastered(uuid,text),private.refresh_resource_profile_authoritative(uuid,text)from public,anon,authenticated;
